css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 6px 12px; margin-bottom: 8px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; margin-bottom: 4px; display: flex; align-items: center; gap: 6px;}
.mz .recuerda-grid{display: grid; grid-template-columns: 1fr 170px; gap: 12px; align-items: center;}
.mz .recuerda-idea{font-size: 12px; line-height: 1.35;}
.mz .recuerda-cubo{display: flex; justify-content: center;}
.mz .tabla-fig{width: 100%; border-collapse: collapse;}
.mz .tabla-fig th{border: 1.5px solid var(--bosque); background: #eee; font-size: 12px; padding: 4px 6px;}
.mz .tabla-fig td{border: 1.5px solid var(--bosque); text-align: center; padding: 2px 6px; height: 43px;}
.mz .celda-nom{width: 30%; font-size: 13px; font-weight: 700;}
.mz .celda-num{width: 22%;}
.mz .unir-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 6px 40px; align-items: center;}
.mz .unir-col{display: flex; flex-direction: column; gap: 4px; align-items: center;}
.mz .unir-fig{display: flex; align-items: center; justify-content: center; min-height: 36px;}
.mz .unir-fig svg{width: 36px; height: 36px;}
.mz .unir-nom{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 6px 8px; text-align: center; font-size: 13px; font-weight: 700; width: 100%;}
.mz .banco{border: 1.5px dashed #000; border-radius: 8px; padding: 5px 10px; text-align: center; font-size: 13px; font-weight: 700; margin-bottom: 6px;}
.mz .clasif-grid{display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px;}
.mz .clasif-caja{border: 1.5px solid var(--bosque); border-radius: 8px; overflow: hidden;}
.mz .clasif-titulo{background: #eee; border-bottom: 1.5px solid var(--bosque); font-size: 12px; font-weight: 700; text-align: center; padding: 3px 2px;}
.mz .clasif-hueco{min-height: 64px; padding: 3px 14px; display: flex; flex-direction: column; justify-content: space-evenly;}
.mz .clasif-linea{border-bottom: 1px solid #999; height: 19px;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 4px;}
.mz .vf-item{display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 13px; border-bottom: 1px dotted #999; padding-bottom: 2px;}
.mz .vf-opciones{font-family: sans-serif; font-weight: 700; font-size: 12.5px; white-space: nowrap;}
.mz .recuerda-idea{line-height: 1.725 !important;}
